plugin.theme:
/* متغيرات المنتدى الأساسية */
:root {
    --startimes-blue: var(--setting-primary);
    --startimes-dark-blue: var(--setting-secondary);
    --startimes-header-bg: linear-gradient(180deg, var(--setting-primary) 0%, var(--setting-secondary) 100%);
    --bg-body: var(--setting-page_bg);
    --border-table: var(--setting-primary);
}

body {
    background-color: var(--setting-page_bg) !important;
}

/* ترويسات الأقسام والجداول والمواضيع */
.table-columns-header,
.table-columns-header th,
.st-thead-row th,
.vb-box-header,
.startimes-topic-blue-banner,
.startimes-topic-bottom-bar {
    background: linear-gradient(90deg, var(--setting-primary) 0%, var(--setting-secondary) 100%) !important;
}

.vb-bottom-box {
    border-bottom-color: var(--setting-primary);
}

/* الروابط عند التحويم */
.st-cat-link:hover {
    color: var(--setting-accent) !important;
}

.vb-box-body a:hover {
    color: var(--setting-accent);
}
